{
  "definition_simple": "虐待；痛苦地对待。",
  "definition_standard": "在精神或肉体上施加痛苦，残酷地对待人或动物。",
  "pos": "动词",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "text": "地主经常苦待穷人。"
    },
    {
      "tier": "T1",
      "text": "我们不应该苦待动物。"
    },
    {
      "tier": "T2",
      "text": "历史上的奴隶常常遭到奴隶主的苦待。"
    },
    {
      "tier": "T3",
      "text": "传说中狠心的继母总是苦待无辜的灰姑娘。"
    },
    {
      "tier": "T4",
      "text": "这部小说深刻揭露了解放前旧社会对底层劳动人民的种种苦待。"
    },
    {
      "tier": "T5",
      "text": "面对命运的百般苦待，他依然保持着乐观向上的生活态度。"
    },
    {
      "tier": "T5",
      "text": "长期遭受精神苦待的她，终于鼓起勇气向心理医生寻求帮助。"
    },
    {
      "tier": "T6",
      "text": "法律严惩那些在养老院里玩忽职守甚至苦待老人的不良护工。"
    },
    {
      "tier": "T6",
      "text": "在战争的残酷岁月中，战俘们不仅身体受创，心灵也饱受敌人的苦待。"
    },
    {
      "tier": "T6",
      "text": "她回顾自己波折的一生，感慨命运虽然曾深深苦待自己，但最终还是迎来了转机。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "库房",
      "explanation": "声母和韵母相似（kù dài 与 kù fáng），读音有一定混淆度，且属于常用词。"
    },
    {
      "word": "酷爱",
      "explanation": "声调和读音高度相似（kù dài 与 kù ài），仅声母与韵尾有细微差别，容易听错。"
    },
    {
      "word": "裤带",
      "explanation": "双音节完全同音（kù dài），仅字形和语义完全不同，是典型的同音词混淆。"
    }
  ],
  "primary_collocate": "命运",
  "collocation_distractors": [
    {
      "word": "天气",
      "explanation": "天气属于自然现象，通常用恶劣、炎热形容，不能作为动词'苦待'的施事或受事搭配。"
    },
    {
      "word": "书本",
      "explanation": "书本是无生命的死物，无法感受到'苦待'带来的痛苦或虐待。"
    },
    {
      "word": "路程",
      "explanation": "路程表示距离或过程，不具备承受虐待或残酷对待的生命属性。"
    }
  ],
  "collocation_wrong_collocate": "空气",
  "cloze_distractors": [
    {
      "word": "优待",
      "explanation": "词义完全相反，'优待'是给予优厚待遇，而句中需要表达残酷对待的意思。"
    },
    {
      "word": "看待",
      "explanation": "词义不符，'看待'表示对人或事物的看法、态度，无法体现折磨或虐待的动作。"
    },
    {
      "word": "期待",
      "explanation": "词义和语境完全不搭，'期待'是等待和盼望，放入句中语法不通且逻辑混乱。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他把这本书苦待在桌子上。",
      "reason": "语义搭配错误，'苦待'只能用于人和动物等有生命主体遭受虐待，不能用于无生命物品的放置。"
    },
    {
      "sentence": "由于工作努力，他得到了老板的苦待。",
      "reason": "逻辑与感情色彩矛盾，'苦待'含有残酷虐待的贬义，工作努力理应受到表扬而非苦待。"
    },
    {
      "sentence": "我们要用爱心去苦待身边的每一个人。",
      "reason": "语义冲突，'爱心'与'苦待'（虐待、残酷对待）的词义完全对立，无法在同一语境中协调使用。"
    }
  ],
  "spot_incorrect": {
    "sentence": "善良的老师从来不会苦待任何一个调皮的学生。",
    "error_description": "'苦待'在现代汉语中多用于书面语或特定文学语境，此处在口语化语境中略显生硬，且逻辑上应使用更常见的'虐待'或'苛待'。",
    "corrected_version": "善良的老师从来不会虐待任何一个调皮的学生。"
  },
